using System.Text;

namespace ZeroInstall.DesktopIntegration.Unix;

/// <summary>
/// Builds key files as specified by the freedesktop.org Desktop Entry Specification.
/// </summary>
internal sealed class KeyFile
{
    /// <summary>
    /// The first line of all generated files.
    /// </summary>
    private const string Marker = "# Generated by Zero Install";

    private readonly StringBuilder _builder = new(Marker + "\n");

    /// <summary>
    /// Starts a new group. All following keys are added to this group.
    /// </summary>
    public KeyFile Group(string name)
    {
        _builder.Append("\n[").Append(name).Append("]\n");
        return this;
    }

    /// <summary>
    /// Adds a key. Does nothing if <paramref name="value"/> is <c>null</c> or empty.
    /// </summary>
    public KeyFile Add(string key, string? value)
        => string.IsNullOrEmpty(value) ? this : AddRaw(key, Escape(value));

    /// <summary>
    /// Adds a boolean key. Does nothing if <paramref name="value"/> is <c>false</c>.
    /// </summary>
    public KeyFile Add(string key, bool value)
        => value ? AddRaw(key, "true") : this;

    /// <summary>
    /// Adds a key holding multiple values. Does nothing if <paramref name="values"/> is empty.
    /// </summary>
    public KeyFile Add(string key, IEnumerable<string> values)
    {
        string value = FormatList(values);
        return value.Length == 0 ? this : AddRaw(key, value);
    }

    private KeyFile AddRaw(string key, string value)
    {
        _builder.Append(key).Append('=').Append(value).Append('\n');
        return this;
    }

    /// <summary>
    /// Formats multiple values for use in a single key.
    /// </summary>
    public static string FormatList(IEnumerable<string> values)
        => string.Concat(values.Select(x => Escape(x).Replace(";", @"\;") + ";"));

    private static string Escape(string value)
    {
        value = value.Replace(@"\", @"\\").Replace("\n", @"\n").Replace("\r", @"\r").Replace("\t", @"\t");
        return value.StartsWithOrdinal(" ") ? @"\s" + value[1..] : value;
    }

    /// <summary>
    /// Returns the contents of the key file.
    /// </summary>
    public override string ToString() => _builder.ToString();

    /// <summary>
    /// Writes the key file to the disk.
    /// </summary>
    /// <param name="path">The path to write to. Existing files are only replaced if they were also generated by Zero Install.</param>
    /// <param name="executable">Mark the file as executable.</param>
    /// <exception cref="IOException">A problem occurred while writing to the filesystem or there already is a file not generated by Zero Install.</exception>
    /// <exception cref="UnauthorizedAccessException">Write access to the filesystem is not permitted.</exception>
    public void Save(string path, bool executable = false)
    {
        if (Directory.Exists(path) || File.Exists(path) && !IsGenerated(path))
            throw new IOException(string.Format(Resources.AliasFileNotOwned, path));

        Log.Debug($"Writing key file: {path}");
        using var atomic = new AtomicWrite(path);
        File.WriteAllText(atomic.WritePath, ToString());
        if (executable) FileUtils.SetExecutable(atomic.WritePath, true);
        atomic.Commit();
    }

    /// <summary>
    /// Deletes a key file if it exists and was generated by Zero Install.
    /// </summary>
    /// <exception cref="IOException">A problem occurred while deleting the file.</exception>
    /// <exception cref="UnauthorizedAccessException">Write access to the filesystem is not permitted.</exception>
    public static void Delete(string path)
    {
        if (!File.Exists(path)) return;

        if (IsGenerated(path)) File.Delete(path);
        else Log.Warn(string.Format(Resources.AliasFileNotOwned, path));
    }

    /// <summary>
    /// Determines whether a file was generated by Zero Install.
    /// </summary>
    public static bool IsGenerated(string path)
        => File.ReadLines(path, Encoding.UTF8).FirstOrDefault() == Marker;
}
